/bin/bash -lc "python - <<'PY'
import urllib.request
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create','https://developers.openai.com/api/docs/guides/your-data']:
    try:
        data=urllib.request.urlopen(url, timeout=25).read().decode()
        import re
        text=re.sub('<["'^>]+>'"', ' ', data)
        text=re.sub(r'\\s+', ' ', text)
        terms=['store','abuse monitoring','30 days','output_text','input']
        print(url)
        for term in terms:
            match=re.search(re.escape(term),text,re.I)
            if match: print(text[max(0,match.start()-150):match.start()+650])
    except Exception as exc: print(type(exc).__name__, str(exc))
PY"

